package edge_tts

import "testing"

// Reference values generated by rany2/edge-tts ba61d944 drm.py, independently
// of the Go port. Include both sides of the five-minute token boundary.
func TestSecMsGecV2ReferenceVectors(t *testing.T) {
	for _, tt := range []struct {
		timestamp int64
		token     string
	}{
		{0, "52BC7A17B50DFEC9-28C4394775C8751CD2F6859C030C06DB1489ACAB3B3A7651831FC26895177ED6"},
		{299, "52BC7A17B50DFEC9-28C4394775C8751CD2F6859C030C06DB1489ACAB3B3A7651831FC26895177ED6"},
		{300, "F7535A20A262E331-28675BF85C7106BBF20035A78FCB0B6890813EAD5C3B983EF3424931B720BABB"},
		{1729980000, "2A16DE69B6BBB133-C22A7F420EA0470383332E9B841336A2B91FFC95693FD5084FB45D4EFB1BBF8D"},
		{1791943200, "513B80B82DE94D98-0234AF70BCC2ABF55B87B56A170CE4A66CD4BF9AB1A79D934E527B68DC75ED17"},
		{1791943499, "513B80B82DE94D98-0234AF70BCC2ABF55B87B56A170CE4A66CD4BF9AB1A79D934E527B68DC75ED17"},
		{1791943500, "6F196B7CB30911DB-F10D0E3E14D0ADBCF9BC98CB68E4CA281087D21B84FC6D75462A2193B7CAA9D6"},
		{2000000000, "2D62557F1142BC5D-FD9C30C68FF194A5EE6B45FEFC5E2BA1D1239F88A90569AB55CFFFAA7799F40E"},
	} {
		if got := generateSecMsGecV2(tt.timestamp); got != tt.token {
			t.Errorf("timestamp %d: got %s, want %s", tt.timestamp, got, tt.token)
		}
	}
}
